// Process marketplace results into normalized lead format
const items = $input.all();
const leads = [];

for (const item of items) {
  const data = item.json;
  if (!data || data.error) continue;

  // Handle array results from Apify
  const results = Array.isArray(data) ? data : [data];

  for (const listing of results) {
    const title = (listing.title || listing.name || '').toLowerCase();
    const description = (listing.description || listing.text || '').toLowerCase();
    const combined = title + ' ' + description;

    // Classify device type
    let deviceType = 'Other';
    if (combined.includes('ps5') || combined.includes('playstation 5') || combined.includes('playstation5')) {
      deviceType = 'PS5';
    } else if (combined.includes('xbox series x')) {
      deviceType = 'Xbox Series X';
    } else if (combined.includes('xbox series s')) {
      deviceType = 'Xbox Series S';
    } else if (combined.includes('xbox')) {
      deviceType = 'Xbox Series X';
    } else if (combined.includes('switch') || combined.includes('nintendo')) {
      deviceType = 'Nintendo Switch';
    } else if (combined.includes('macbook') || combined.includes('mac book')) {
      deviceType = 'MacBook';
    } else if (combined.includes('laptop') || combined.includes('notebook')) {
      deviceType = 'Laptop';
    }

    // Extract condition keywords found
    const conditionTerms = ['broken', 'not working', 'for parts', 'cracked', 'dead',
      'damaged', 'won\'t turn on', 'defective', 'faulty', 'water damage',
      'as-is', 'as is', 'needs repair', 'bricked', 'doesnt work', 'doesn\'t work'];
    const foundConditions = conditionTerms.filter(term => combined.includes(term));

    if (foundConditions.length === 0 && deviceType === 'Other') continue;

    leads.push({
      json: {
        lead_id: 'MKT-' + Date.now() + '-' + Math.random().toString(36).substr(2, 6),
        source: 'marketplace',
        platform_post_id: listing.id || listing.postId || listing.url || '',
        seller_name: listing.sellerName || listing.author || listing.userName || '',
        seller_profile_url: listing.sellerUrl || listing.authorUrl || listing.userProfileUrl || '',
        device_type: deviceType,
        listing_title: listing.title || listing.name || '',
        listing_description: listing.description || listing.text || '',
        listing_price: parseFloat(String(listing.price || '0').replace(/[^0-9.]/g, '')) || 0,
        listing_url: listing.url || listing.postUrl || '',
        listing_images: JSON.stringify(listing.images || listing.photos || []),
        location: listing.location || listing.city || '',
        condition_keywords: foundConditions.join(', '),
        status: 'new',
        scraped_at: new Date().toISOString()
      }
    });
  }
}

return leads.length > 0 ? leads : [{ json: { _empty: true, source: 'marketplace' } }];

// Process group post results into normalized lead format
const items = $input.all();
const leads = [];

const devicePatterns = [
  { pattern: /ps5|playstation\s*5/i, type: 'PS5' },
  { pattern: /xbox\s*series\s*x/i, type: 'Xbox Series X' },
  { pattern: /xbox\s*series\s*s/i, type: 'Xbox Series S' },
  { pattern: /xbox/i, type: 'Xbox Series X' },
  { pattern: /switch|nintendo/i, type: 'Nintendo Switch' },
  { pattern: /macbook|mac\s*book/i, type: 'MacBook' },
  { pattern: /laptop|notebook/i, type: 'Laptop' }
];

const conditionTerms = ['broken', 'not working', 'for parts', 'cracked', 'dead',
  'damaged', 'won\'t turn on', 'defective', 'faulty', 'water damage',
  'as-is', 'as is', 'needs repair', 'bricked', 'doesnt work', 'doesn\'t work',
  'selling for parts', 'parts only'];

for (const item of items) {
  const data = item.json;
  if (!data || data.error) continue;

  const results = Array.isArray(data) ? data : [data];

  for (const post of results) {
    const text = (post.text || post.message || post.content || '').toLowerCase();
    const title = (post.title || '').toLowerCase();
    const combined = title + ' ' + text;

    // Check if post mentions broken electronics
    const foundConditions = conditionTerms.filter(term => combined.includes(term));
    if (foundConditions.length === 0) continue;

    // Classify device
    let deviceType = 'Other';
    for (const dp of devicePatterns) {
      if (dp.pattern.test(combined)) {
        deviceType = dp.type;
        break;
      }
    }

    // Only include if we found a recognizable device
    if (deviceType === 'Other') continue;

    // Try to extract price from text
    const priceMatch = combined.match(/\$\s*(\d+(?:\.\d{2})?)|\b(\d+)\s*(?:dollars|obo|firm)/i);
    const price = priceMatch ? parseFloat(priceMatch[1] || priceMatch[2]) : 0;

    leads.push({
      json: {
        lead_id: 'GRP-' + Date.now() + '-' + Math.random().toString(36).substr(2, 6),
        source: 'group',
        platform_post_id: post.id || post.postId || post.url || '',
        seller_name: post.authorName || post.userName || post.author || '',
        seller_profile_url: post.authorUrl || post.userProfileUrl || '',
        device_type: deviceType,
        listing_title: post.title || text.substring(0, 80) + '...',
        listing_description: post.text || post.message || post.content || '',
        listing_price: price,
        listing_url: post.url || post.postUrl || '',
        listing_images: JSON.stringify(post.images || post.photos || []),
        location: post.location || '',
        condition_keywords: foundConditions.join(', '),
        status: 'new',
        scraped_at: new Date().toISOString()
      }
    });
  }
}

return leads.length > 0 ? leads : [{ json: { _empty: true, source: 'group' } }];

// Filter out empty results and deduplicate by platform_post_id
const items = $input.all();
const seen = new Set();
const leads = [];

for (const item of items) {
  if (item.json._empty) continue;

  const postId = item.json.platform_post_id;
  if (postId && seen.has(postId)) continue;
  if (postId) seen.add(postId);

  leads.push(item);
}

return leads.length > 0 ? leads : [{ json: { _no_new_leads: true } }];

// Compare new leads against existing Google Sheet data
const existingRows = $input.all();
const deduplicatedLeads = $('Deduplicate').all().filter(item => !item.json._no_new_leads);

if (deduplicatedLeads.length === 0) {
  return [{ json: { _all_exist: true } }];
}

// Build set of existing platform post IDs
const existingPostIds = new Set();
for (const row of existingRows) {
  if (row.json.platform_post_id) {
    existingPostIds.add(row.json.platform_post_id);
  }
}

// Return only leads not already in the sheet
const newOnly = deduplicatedLeads.filter(lead =>
  !existingPostIds.has(lead.json.platform_post_id)
);

return newOnly.length > 0 ? newOnly : [{ json: { _all_exist: true } }];
